const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',radar:'<circle cx="12" cy="12" r="9"/><path d="M12 3v9l6-5M5 15a7 7 0 0 0 10 4"/><circle cx="8" cy="11" r="1"/>',feed:'<path d="M3 6h5m4 0h9M3 12h9m4 0h5M3 18h3m4 0h11"/><circle cx="10" cy="6" r="2"/><circle cx="14" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',book:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2M3 12c5 3 13 3 18 0m-10 1h2v3h-2z"/>',log:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6m-6 4h6m-6 4h4"/>',pipeline:'<rect x="9" y="3" width="6" height="5" rx="1"/><rect x="2" y="16" width="6" height="5" rx="1"/><rect x="16" y="16" width="6" height="5" rx="1"/><path d="M12 8v4H5v4m7-4h7v4"/>',shield:'<path d="M12 3 4 6v6c0 5 5 8 8 10 3-2 8-5 8-10V6z"/><path d="m8.5 12 2.3 2.3 4.7-4.8"/>',moon:'<path d="M20 14a8.5 8.5 0 0 1-10-11A9.2 9.2 0 1 0 21 15z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',pause:'<path d="M8 5v14m8-14v14" stroke-width="3"/>',play:'<path d="m7 4 13 8-13 8z"/>',scan:'<path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m8 0h3a2 2 0 0 0 2-2v-3M3 12h18"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-2L3 9m0-6v6h6m-5 7a8 8 0 0 0 14 2l3-3m0 6v-6h-6"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',ne:'<path d="M6 18 18 6M6 6h12v12"/>',chev:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',down:'<path d="m5 9 7 7 7-7"/>',chevup:'<path d="m5 15 7-7 7 7"/>',wallet:'<path d="M20 8V5a1 1 0 0 0-1-1L5 6a2 2 0 0 0-1 2v10a2 2 0 0 0 2 2h14V8H6"/><path d="M20 11h-5v5h5"/><circle cx="17" cy="13.5" r=".5"/>',trend:'<path d="m3 17 6-6 4 3 8-9m-6 0h6v6"/>',layers:'<path d="m12 3 10 5-10 5L2 8zM3 12l9 5 9-5M3 16l9 5 9-5"/>',filter:'<path d="M3 4h18l-7 8v6l-4 3v-9z"/>',analyst:'<path d="M4 20V4m0 16h17M8 16v-4m5 4V6m5 10V9"/>',bolt:'<path d="m14 2-11 12h8l-1 8 11-13h-8z"/>',check:'<path d="m4 12 5 5L20 6"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9h.01"/>',alert:'<path d="M10.4 4.5 2.8 18a1.8 1.8 0 0 0 1.5 2.7h15.4a1.8 1.8 0 0 0 1.5-2.7L13.6 4.5a1.9 1.9 0 0 0-3.2 0Z"/><path d="M12 8v5m0 3h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',export:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v13h5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c3 4 13 4 16 0V5M4 12c3 4 13 4 16 0"/>',target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',sliders:'<path d="M4 7h4m5 0h7M4 17h9m5 0h2"/><circle cx="10" cy="7" r="2.5"/><circle cx="15.5" cy="17" r="2.5"/>',terminal:'<path d="m4 6 6 6-6 6m9 0h7"/>',file:'<path d="M6 3h8l5 5v13H6zM14 3v6h5M9 13h7m-7 4h5"/>',route:'<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 6h7a3 3 0 0 1 0 6h-4a3 3 0 0 0 0 6h7"/>'};
const ico=(s,cls='')=>`<svg class="${cls}" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[s]||paths.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const $=s=>document.querySelector(s);const fmt=(n,places=0)=>n==null?'—':Number(n).toLocaleString('en-US',{minimumFractionDigits:places,maximumFractionDigits:places});const cash=(n,d=2)=>n==null?'—':'$'+fmt(n,d);const numshort=n=>n==null?'—':Math.abs(n)>=1e6?fmt(n/1e6,2)+'M':Math.abs(n)>=1000?fmt(n/1000,1)+'K':fmt(n);const usd=n=>n==null?'—':'$'+numshort(n);const sign=n=>n>0?'+':n<0?'−':'';const pc=n=>n==null?'—':sign(n)+fmt(Math.abs(n),2)+'%';const price=n=>n==null?'—':'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumSignificantDigits:5});const hh=(t,sec=false)=>t?new Date(t*1000).toLocaleTimeString('en-GB',{timeZone:'Africa/Kampala',hour:'2-digit',minute:'2-digit',...(sec?{second:'2-digit'}:{})}):'—';const day=t=>new Date(t*1000).toLocaleDateString('en-GB',{timeZone:'Africa/Kampala',day:'2-digit',month:'short',year:'numeric'});const duration=s=>s<0?'0m':s<3600?Math.floor(s/60)+'m':Math.floor(s/3600)+'h '+Math.floor((s%3600)/60)+'m';const age=t=>t?duration(now()-t):'—';const pad=x=>String(x).padStart(2,'0');const short=s=>s?esc(s.slice(0,6)+'…'+s.slice(-5)):'—';const finite=n=>Number.isFinite(n);const $main=$('#main');
const tabs=[['overview','Desk overview','grid'],['feed','Candidate feed','radar'],['book','Paper portfolio','book'],['log','Audit log','log'],['agents','Agent pipeline','pipeline'],['policy','Risk policy','shield']];
const agents=[{name:'Scout',icon:'radar',role:'Discovery',color:'#c4e8a4',bg:'#2c3925',desc:'Discovers Solana pairs, then verifies age and market cap against DexScreener.',out:'An in-range pair with its exact mint, pool, age and market cap.'},{name:'Filter',icon:'filter',role:'Validation',color:'#e5bf8b',bg:'#372f22',desc:'Checks all ten hard gates. A failed or unverifiable check kills the handoff.',out:'A full evidence record. No partial passes and no missing-data defaults.'},{name:'Analyst',icon:'analyst',role:'Scoring',color:'#bfa8e5',bg:'#302a3b',desc:'Scores six observed factors. Only a complete score of 70 or better can advance.',out:'An evidence-backed score, with the contribution of every factor.'},{name:'Risk',icon:'shield',role:'Authorization',color:'#8bcbdc',bg:'#23353a',desc:'Rechecks the market, caps all-in size and authorizes a specific −6% stop before entry.',out:'A short-lived permit containing quantity, budget, reference swap and stop.'},{name:'Executor',icon:'bolt',role:'Paper fills',color:'#e7d69a',bg:'#363323',desc:'Consumes a fresh Risk permit, debits simulated cash, and books the paper fill atomically.',out:'A paper position. There is no transaction builder, signer or live mode.'},{name:'Logger',icon:'log',role:'Audit trail',color:'#bcc9b6',bg:'#2c3329',desc:'Records every rejection, handoff, source issue and fill in an append-only ledger.',out:'Timestamped audit evidence, a CSV export and a report at session close.'}];
const bgstyle=a=>`--accent:${a.color};--tint:${a.bg}`;const alabel=a=>`<span class="agent-icon" style="${bgstyle(a)}">${ico(a.icon)}</span>`;const slabel={killed:['Killed','x'],unverified:['Unverified','info'],blocked:['Blocked','lock'],qualified:['Qualified','check'],cleared:['Cleared','check'],screening:['Screening','scan'],paper:['Paper fill','check'],out:['Out of range','filter']};const badge=s=>`<span class="badge ${esc(s)}" title="${s==='unverified'?'Rejected: required evidence could not be verified':s==='killed'?'Rejected by a hard gate':esc((slabel[s]||[s])[0])}">${ico((slabel[s]||['','info'])[1])}${esc((slabel[s]||[s])[0])}</span>`;
let S=null,page='overview',delta=0,offline=false,busy=false,timerToast,modalSeq=0,logSeq=0,drawerKind='',chartPair='',chartRange='1H',logData=null,logState={q:'',kind:'',agent:'',offset:0},feedState={q:'',filter:'all',sort:'score',dir:-1},bookTab='open',failedIcons=new Set(),polling=false;
const now=()=>Date.now()/1000+delta;const sourceStale=()=>!S||offline||now()-S.session.heartbeat>75;const scanStale=()=>!S||!S.session.last_scan||now()-S.session.last_scan>420;const selTab=()=>{const h=location.hash.slice(1).split('?')[0];return tabs.some(t=>t[0]===h)?h:'overview'};const countNow=()=>S?S.stats.in_range:0;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(timerToast);timerToast=setTimeout(()=>el.classList.remove('show'),3600)}
async function api(u,opts){const r=await fetch(u,{cache:'no-store',...opts});const d=await r.json();if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);return d}
function nav(){const create=t=>`<a href="#${t[0]}" class="navlink ${page===t[0]?'on':''}" ${page===t[0]?'aria-current="page"':''} title="${t[1]}">${ico(t[2])}<span class="navtext">${t[1]}</span>${t[0]==='feed'?`<span class="nav-count">${countNow()}</span>`:''}</a>`;$('#workspace-nav').innerHTML=tabs.slice(0,4).map(create).join('');$('#system-nav').innerHTML=tabs.slice(4).map(create).join('');$('#crumb-page').textContent=page==='overview'?'Overview':tabs.find(t=>t[0]===page)[1];$('.crumb-icon').innerHTML=ico('layers');$('#mobile-menu').innerHTML=ico('menu');if(!S)return;const s=S.session;$('#side-session').innerHTML=`<button data-session style="display:block;text-align:left;padding:0;width:100%" title="Inspect session window"><span class="micro">${ico('moon')}Session window</span><strong>${s.mode==='ended'?'Session complete':s.mode==='paused'?'Session paused':s.mode==='closing'?'Closing session':'Overnight session'}</strong><p>${s.mode==='ended'?'Paper ledger saved':`Until ${hh(s.end)} EAT`}</p><div class="session-bar"><i style="width:${Math.max(0,Math.min(100,100*(now()-s.start)/(s.end-s.start)))}%"></i></div><span class="session-time"><span>${hh(s.start)}</span><span>${hh(s.end)}</span></span></button>`}
function head(ey,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${ey}</div><div class="title-row"><h1>${title}</h1>${title==='Desk overview'?liveFlag():''}</div><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function buttons(){const mode=S.session.mode,paused=mode==='paused';return mode==='ended'?`<a class="btn" href="/api/report" download>${ico('export')}Session report</a><button class="btn solid" data-action="new">${ico('moon')}New session</button>`:mode==='closing'?`<span class="pill">Reconciling positions</span>`:`<button class="btn" data-action="${paused?'resume':'pause'}" ${busy?'disabled':''}>${ico(paused?'play':'pause')}${paused?'Resume':'Pause'}</button><button class="btn solid" data-action="scan" ${busy||S.scanning||paused||sourceStale()?'disabled':''}>${ico(S.scanning?'refresh':'scan',S.scanning?'spin':'')}${S.scanning?'Scanning…':'Scan now'}</button>`}
function liveFlag(){const live=!sourceStale()&&S.session.mode==='running';return `<span class="liveflag ${live?'':'off'}"><i class="small-dot"></i>${live?'Session live':sourceStale()?'Disconnected':esc(S.session.mode)}</span>`}
function radar(){const cx=150,cy=119,rr=93;const pt=(r,a)=>[cx+r*Math.cos(a),cy+r*Math.sin(a)];let grid='',ticks='',sweep='';for(let i=0;i<72;i++){const a=i*Math.PI/36,b=pt(rr+5,a),e=pt(rr+(i%6===0?11:7.3),a);ticks+=`<path d="M${b}L${e}" stroke="${i%6===0?'#718361':'#435139'}" stroke-width="${i%6===0?1.2:.85}"/>`}for(let i=0;i<12;i++){const v=pt(rr,i*Math.PI/6);grid+=`<path d="M150 119L${v}" stroke="#748962" stroke-opacity=".32" stroke-width=".7"/>`}for(let i=1;i<=4;i++){grid+=`<circle cx="150" cy="119" r="${rr*i/4}" fill="none" stroke="#849a6b" stroke-width="${i===4?.95:.7}" opacity="${i===4?.6:.46}"/>`}for(let i=0;i<26;i++){const a=pt(rr,(-94+i*2)*Math.PI/180),b=pt(rr,(-92+i*2)*Math.PI/180);sweep+=`<path d="M150 119L${a}L${b}Z" fill="#b0ed69" opacity="${.019+i*.010}"/>`}const end=pt(rr,(-94+52)*Math.PI/180);sweep+=`<path d="M150 119L${end}" stroke="#bee580" stroke-width="1" opacity=".7"/>`;let labels=[];const dots=S.pairs.filter(p=>p.created&&p.mcap).map((p,i)=>{const a=(now()-p.created)/3600/72*Math.PI*2-Math.PI/2,r=21+Math.max(0,Math.min(1,Math.log(p.mcap/3e5)/Math.log(2e7/3e5)))*68;const [x,y]=pt(r,a);let lab='';if(labels.length<2&&(!labels[0]||Math.hypot(x-labels[0][0],y-labels[0][1])>27)){labels.push([x,y]);const right=x>=cx-1,dx=right?1:-1,tx=x+dx*18,ty=y-14;lab=`<path d="M${x} ${y}l${dx*7} -10h${dx*8}" fill="none" stroke="#badb91" opacity=".6" stroke-width=".8"/><text x="${tx}" y="${ty+6}" text-anchor="${right?'start':'end'}" font-size="7.4" font-family="Plex,monospace" fill="#cfdfbd" style="paint-order:stroke;stroke:#202b19;stroke-width:3px">${esc(p.symbol.slice(0,9))}</text>`}return `<g class="radar-blip" data-pair="${esc(p.pair)}" tabindex="0" role="button" aria-label="Inspect ${esc(p.symbol)}"><title>${esc(p.symbol)} · ${usd(p.mcap)} · ${age(p.created)}</title><circle cx="${x}" cy="${y}" r="9" fill="transparent"/><circle cx="${x}" cy="${y}" r="8" fill="#b4e770" opacity=".09"/><circle cx="${x}" cy="${y}" r="5.1" fill="none" stroke="#c0f877" opacity=".38" stroke-width=".65"/><circle class="core" cx="${x}" cy="${y}" r="2.6" fill="#d5ff9b"/>${lab}</g>`}).join('');return `<svg viewBox="0 0 300 240" aria-label="Discovery radar. Angle is pair age, radius is logarithmic market cap. Each point opens a real pair."><defs><radialGradient id="rglow"><stop stop-color="#455a30" stop-opacity=".3"/><stop offset="1" stop-color="#2c3924" stop-opacity=".13"/></radialGradient></defs><circle cx="150" cy="119" r="93" fill="url(#rglow)"/><g>${grid}${ticks}</g><path d="M35 119H265M150 7V230" stroke="#869875" stroke-dasharray="2 6" stroke-width=".65" opacity=".45"/><g class="radar-sweep">${sweep}</g><circle cx="150" cy="119" r="2" fill="#a3bf89"/>${dots}<g fill="#96a788" font-family="Plex,monospace" font-size="6.5" letter-spacing=".5"><text x="150" y="9" text-anchor="middle">00H</text><text x="260" y="122">18H</text><text x="150" y="234" text-anchor="middle">36H</text><text x="27" y="122">54H</text></g></svg>`}
function equityGraph(){const data=S.equity_history;if(data.length<2)return `<div class="equity-line" title="Awaiting a second recorded equity sample"></div>`;const vals=data.map(v=>v.value),lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max((hi-lo)*1.4,Math.max(hi,1)*.001),mid=(lo+hi)/2,t0=data[0].ts,t1=data.at(-1).ts;const pts=data.map(o=>[2+(o.ts-t0)/Math.max(1,t1-t0)*296,24-(o.value-mid)/span*32]);const path=pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');return `<div class="equity-line" title="Recorded paper equity · ${data.length} samples"><svg viewBox="0 0 300 45" preserveAspectRatio="none"><defs><linearGradient id="eqfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a9d579" stop-opacity=".12"/><stop offset="1" stop-color="#a9d579" stop-opacity="0"/></linearGradient></defs><path d="M0 10H300 M0 37H300" stroke="#343b2f" stroke-dasharray="2 5" stroke-width=".7"/><path d="${path}L298 45H2Z" fill="url(#eqfill)"/><path d="${path}" stroke="#a2c780" fill="none" stroke-width="1.4" vector-effect="non-scaling-stroke"/><circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="2.3" fill="#c2e9a0"/></svg></div>`}
function overviewHero(){const b=S.book,v=fmt(b.equity,2).split('.');return `<div class="hero-grid"><section class="panel radar-panel"><div class="radar-corner"></div><div class="radar-corner two"></div><div class="radar-info"><div class="readout"><i class="small-dot"></i>SCOUT TELEMETRY</div><h2>Discovery radar</h2><p>Fresh pairs in the target universe.</p><div class="radar-stats"><div><strong>${fmt(S.stats.screened)}</strong><small>Pairs screened</small></div><div><strong>${pad(S.stats.in_range)}</strong><small>In range</small></div></div><div class="scope-tags"><span>${ico('clock')}30m–72h</span><span>${ico('layers')}$300K–$20M</span></div></div><div class="radar-graphic ${S.session.mode!=='running'||sourceStale()?'paused':''}">${radar()}</div></section><section class="panel paper-card"><div class="capline"><span class="cap-title">${ico('wallet')}Paper equity</span><a class="paper-tag" href="#book" title="See execution readiness and forward results">PAPER ${ico('ne')}</a></div><h2>$${v[0]}<small>.${v[1]}</small></h2><div class="pnl ${b.pnl<0?'negative':''}">${ico(b.pnl===0?'arrow':'trend')}${sign(b.pnl)}${cash(Math.abs(b.pnl))} (${pc(b.pnl/S.session.seed*100)}) <span>session P&amp;L</span></div>${equityGraph()}<div class="paper-bottom"><div><span>Available cash</span><b>${cash(b.cash)}</b></div><div><span>Open positions</span><b>${pad(b.open)}</b></div></div></section></div>`}
function pipeline(){return `<section class="panel pipeline block-gap"><div class="panel-head"><div class="heading-line"><h2>Agent pipeline</h2><span class="tiny-pip">Hard handoffs</span></div><a class="linkbtn" href="#agents">Inspect ${ico('arrow')}</a></div><div class="chain">${agents.map((a,i)=>`<button class="node ${S.agents[i].working?'active':''}" style="${bgstyle(a)}" data-agent="${a.name}"><div class="node-top">${alabel(a)}<span class="node-num">0${i+1}</span></div><span class="node-name">${a.name}</span><span class="node-role">${a.role}</span></button>`).join('')}</div></section>`}
const palette=[['#3a472d','#d3e3a8'],['#443346','#e6c3e4'],['#39414d','#b9d4e5'],['#4c3c2b','#e5d09e'],['#2d4844','#ade0d2'],['#443332','#edc4b6']];function avatar(p){const hash=[...(p.mint||p.symbol||'N')].reduce((n,c)=>n+c.charCodeAt(0),0),c=palette[hash%palette.length];return `<span class="avatar" style="--avatarbg:${c[0]};--avatarfg:${c[1]}">${esc((p.symbol||'?').slice(0,2).toUpperCase())}${p.mint&&!failedIcons.has(p.mint)?`<img loading="lazy" data-mint="${esc(p.mint)}" src="/assets/tokens/${esc(p.mint)}.webp" alt="">`:''}</span>`}document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.mint){failedIcons.add(e.target.dataset.mint);e.target.remove()}},true);
function coin(p){return `<span class="coin">${avatar(p)}<span><strong>${esc(p.symbol)}</strong><small>${esc(p.name||p.dex)}</small></span></span>`}
function filtPairs(){let rows=S.pairs.filter(p=>(!feedState.q||[p.symbol,p.name,p.mint,p.pair].some(x=>(x||'').toLowerCase().includes(feedState.q.toLowerCase())))&&(feedState.filter==='all'||(feedState.filter==='qualified'?p.score!=null&&p.score>=70:['killed','unverified','blocked'].includes(p.status))));const k=feedState.sort;return rows.sort((a,b)=>((a[k]??-Infinity)-(b[k]??-Infinity))*feedState.dir*(k==='created'?-1:1)||((b.vol||0)-(a.vol||0)))}
function empty(ic,title,desc,action=''){return `<div class="empty"><span class="emptyicon">${ico(ic)}</span><b>${title}</b><p>${desc}</p>${action}</div>`}
function feedRows(rows,full){return rows.map(p=>`<tr class="clickrow" data-pair="${esc(p.pair)}" tabindex="0" aria-label="Inspect ${esc(p.symbol)}"><td>${coin(p)}</td><td class="muted">${age(p.created)}</td><td>${usd(p.mcap)}</td><td>${usd(p.liq)}</td><td class="optional-col">${usd(p.vol)}</td><td class="${p.change>0?'positive':p.change<0?'negative':''}">${pc(p.change)}</td>${full?`<td>${p.score==null?'<span class="dim">—</span>':fmt(p.score,1)}</td>`:''}<td>${badge(p.status)}</td><td>${ico('chev','row-arrow')}</td></tr>`).join('')}
function feedTable(full=false){const rows=full?filtPairs():S.pairs.slice(0,5);let h=(label,key,c='')=>`<th class="${c}">${full&&key?`<button class="thsort" data-sort="${key}">${label} ${feedState.sort===key?(feedState.dir<0?'↓':'↑'):''}</button>`:label}</th>`;return `<section class="panel feed-panel ${full?'':'block-gap'}"><div class="panel-head"><div><div class="heading-line"><h2>${full?'In-range pairs':'Candidate feed'}</h2><span class="tiny-pip">${pad(S.stats.in_range)}</span></div><p class="sub">${full?'All detections from the latest discovery cycle.':'Latest in-range detections and their gate decisions.'}</p></div><div class="panel-actions">${full?liveFlag():`<span class="data-tag"><i class="small-dot"></i>SCAN ${String(S.scan).padStart(3,'0')}</span><a class="linkbtn" href="#feed">View feed ${ico('arrow')}</a>`}</div></div>${full?`<div class="controls"><div class="segmented">${[['all','All pairs'],['qualified','Qualified'],['rejected','Rejected']].map(([k,v])=>`<button data-filter="${k}" class="${feedState.filter===k?'sel':''}">${v}</button>`).join('')}</div><label class="searchbox">${ico('search')}<input id="feed-search" type="search" value="${esc(feedState.q)}" placeholder="Find token or mint…" aria-label="Search candidate feed" autocomplete="off"></label></div>`:''}<div class="table-wrap"><table><thead><tr>${h('Token')}${h('Age','created')}${h('Market cap','mcap')}${h('Liquidity','liq')}${h('1h volume','vol','optional-col')}${h('1h move','change')}${full?h('Score','score'):''}${h('Decision')}${h('')}</tr></thead><tbody id="feed-body">${feedRows(rows,full)}</tbody></table></div><div id="feed-empty">${rows.length?'':empty('radar',full&&feedState.filter==='qualified'?'No qualified signals':'No matching pairs',full&&feedState.filter==='qualified'?'A complete Filter pass and a score of at least 70 are required.':'The feed only shows pairs observed inside the Scout universe.')}</div><div class="table-foot"><span>${ico('database')}DexScreener · Solana<button class="evidence-link" data-sources title="Inspect upstream data availability">${Object.values(S.feeds).some(f=>!f.ok)?'Evidence gaps '+ico('info'):'Source health '+ico('info')}</button></span><span>${S.scanning?'Cycle in progress':`${scanStale()?'Last observation':'Last scan'} ${hh(S.session.last_scan,true)} EAT`}</span></div></section>`}
const kindClass=k=>({KILL:'kill',ERROR:'kill',SOURCE:'source',HANDOFF:'handoff',ENTRY:'entry',EXIT:'exit'}[k]||'neutral');const kindBadge=k=>`<span class="badge kind-${kindClass(k)}">${esc(k)}</span>`;
function miniAudit(){return `<section class="panel"><div class="panel-head"><div class="heading-line"><h2>Recent activity</h2></div><a href="#log" class="linkbtn">Audit log ${ico('arrow')}</a></div>${S.events.slice(0,4).map(x=>`<button class="audit-mini" data-event="${x.id}"><span class="log-glyph">${ico(x.kind==='KILL'?'filter':x.kind==='CYCLE'?'log':'pulse')}</span><span class="log-body"><strong>${esc(x.agent)}${x.symbol?' · '+esc(x.symbol):''}</strong><p>${esc(x.reason)}</p></span><time>${hh(x.ts,true)}</time></button>`).join('')||empty('clock','Awaiting the first event','The Logger will append the first live observation here.')}</section>`}
function guardSummary(){return `<section class="panel"><div class="panel-head"><h2>Risk guardrails</h2><a href="#policy" class="linkbtn">Policy ${ico('arrow')}</a></div><div class="guard-list">${[['wallet','Max allocation','8% / trade'],['shield','Initial stop','−6%'],['trend','Trail activation','+12%'],['target','Minimum score','70 / 100']].map(v=>`<div class="guard-line"><span>${ico(v[0])}${v[1]}</span><b>${v[2]}</b></div>`).join('')}</div></section>`}
function kpi(label,v,sub,cl=''){return `<div class="panel mini-kpi"><span>${label}</span><strong class="${cl}">${v}</strong><small>${sub}</small></div>`}
function paperReadiness(){const r=S.readiness;if(!r)return '';const f=r.performance,rt=r.runtime_ready&&!sourceStale();const gaps=Object.entries(r.unknown_gates).map(([k,n])=>esc(k)+' ('+n+')').join(', ');const probes=r.tape_checks||[],tested=probes.filter(x=>x.ok).length;
const row=(label,value,sub='',warn=false)=>`<div class="proof-row"><div><span>${label}</span>${sub?`<small>${sub}</small>`:''}</div><b class="${warn?'proof-warn':''}">${value}</b></div>`;
return `<div class="two-col proof-grid"><section class="panel"><div class="panel-head"><div><div class="heading-line"><h2>Execution readiness</h2><span class="paper-tag">PAPER</span></div><p>Runtime health is separate from trade approval.</p></div></div><div class="proof-body"><div class="proof-banner ${rt?'':'alerted'}">${ico(rt?'shield':'alert')}<strong>${rt?'Paper controls armed':'New entries blocked'}</strong></div>${!rt&&r.runtime_blockers.length?`<p class="proof-note">${r.runtime_blockers.map(esc).join(' · ')}</p>`:''}${row('Stop monitor',r.watchdog_healthy&&!sourceStale()?'Current':'Not current','A gap over 60s blocks new entries.',!r.watchdog_healthy||sourceStale())}${row('Cash reconciliation',r.cash_reconciliation.ok?'Balanced':'Mismatch','Cash checked against booked debits and exits.',!r.cash_reconciliation.ok)}${row('Two-sided tape',probes.length?tested+' / '+probes.length:'Not sampled','Recent buy and sell prints in sampled pools last cycle; not a route quote.',probes.length>0&&!tested)}${row('Qualified signals',String(r.qualified_in_cycle),'Last completed cycle · '+(r.cycle||'—'))}<p class="proof-note">${gaps?'Missing filter evidence: '+gaps+'.':'No missing Filter fields logged in this cycle. Early kills may skip remaining checks.'}</p></div></section><section class="panel"><div class="panel-head"><div><h2>Forward paper scorecard</h2><p>Closed trades only. No backtests or diagnostic fills.</p></div></div><div class="proof-body"><div class="proof-hero"><small>REALIZED NET P&amp;L</small><b class="${f.net_realized<0?'negative':f.net_realized>0?'positive':''}">${sign(f.net_realized)+cash(Math.abs(f.net_realized))}</b><span>${f.closed} closed round trip${f.closed===1?'':'s'} · this session</span></div>${row('Win rate',f.win_rate_pct==null?'—':fmt(f.win_rate_pct,1)+'%')}${row('Average net per trade',f.avg_net_per_close==null?'—':sign(f.avg_net_per_close)+cash(Math.abs(f.avg_net_per_close)))}${row('Sampled maximum drawdown',f.sampled_max_drawdown_pct==null?'—':fmt(f.sampled_max_drawdown_pct,2)+'%','Based on recorded equity marks, not every tick.')}<p class="proof-note">${f.closed?'Net of modeled fees, slippage and impact. Paper returns need not persist.':'No completed trade: win rate and average return are not yet measurable.'}</p></div></section></div>`}
function bookPage(){const b=S.book,rows=b.positions.filter(p=>bookTab==='open'?!p.closed:p.closed);return head('PAPER ACCOUNT','Paper portfolio','Simulated positions, protective stops and net performance.',`<span class="paper-tag">NO REAL FUNDS</span>`)+`<div class="mini-kpi-grid">${kpi('Paper equity',cash(b.equity),'Marked open positions + cash')}${kpi('Available cash',cash(b.cash),'Unallocated paper capital')}${kpi('Session P&L',sign(b.pnl)+cash(Math.abs(b.pnl)),'Net of modeled fill costs',b.pnl<0?'negative':'positive')}${kpi('Exposure',cash(b.exposure),pad(b.open)+' open positions')}</div>${paperReadiness()}${b.stale?`<div class="callout amber">${ico('alert')}A position is using its last known mark. New entries are blocked.</div>`:''}<section class="panel"><div class="panel-head"><h2>Position ledger</h2><div class="segmented">${['open','closed'].map(k=>`<button class="${bookTab===k?'sel':''}" data-book="${k}">${k==='open'?'Open':'Closed'} · ${b.positions.filter(p=>k==='open'?!p.closed:p.closed).length}</button>`).join('')}</div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Token</th><th>Allocated</th><th>Entry</th><th>${bookTab==='open'?'Mark':'Exit'}</th><th>Stop</th><th>Net P&L</th><th></th></tr></thead><tbody>${rows.map(p=>{const net=(p.closed?p.proceeds:p.qty*p.mark)-p.cost;return `<tr class="clickrow" data-position="${p.id}" tabindex="0"><td>${coin({...p,name:hh(p.entered)+' EAT'})}</td><td>${cash(p.cost)}</td><td>${price(p.entry)}</td><td>${price(p.closed?p.exit:p.mark)}</td><td>${price(p.stop)}</td><td class="${net<0?'negative':'positive'}">${sign(net)}${cash(Math.abs(net))}</td><td>${ico('chev','row-arrow')}</td></tr>`}).join('')}</tbody></table></div>`:empty('book',bookTab==='open'?'No open paper positions':'No closed paper positions',bookTab==='open'?'Capital stays in cash until a pair clears all hard gates, scores 70+, and receives a pre-entry stop.':'Closed positions appear here with net P&L, exit reason and a reference swap.',`<a href="#feed" class="btn sm">Inspect candidate feed ${ico('arrow')}</a>`)}<div class="book-note">Paper fills include a 0.30% fee per side, 0.25% slippage and estimated liquidity impact. Stops are triggers, not guaranteed fill prices.</div></section><div class="two-col block-gap">${guardSummary()}${sources()}</div>`}
function sources(){const names=['DexScreener','Solana RPC','RugCheck','GeckoTerminal','TrenchBot'];if(S.feeds.SolanaTracker)names.push('SolanaTracker');return `<section class="panel"><div class="panel-head"><h2>Data sources</h2><span class="tiny-pip">Read only</span></div><div class="sourcelist">${names.map(n=>{const h=S.feeds[n],st=h&&now()-h.at>420;return `<div class="sourceline"><div><strong>${n}</strong><small>${esc(h?(h.ok?'Last response '+hh(h.at,true)+' EAT':h.note):'Not requested this run')}</small></div><span class="indicator ${!h||!h.ok||st?'warn':''}">${h?(st?'Stale':h.ok?'Connected':'Unavailable'):'Standby'}</span></div>`}).join('')}</div></section>`}
function agentPage(){return head('SYSTEM / WORKFLOW','Agent pipeline','Six specialized agents. Each handoff requires the previous stage’s evidence.',liveFlag())+`<div class="agent-list">${agents.map((a,i)=>{const v=S.agents[i];return `<article class="panel agent-card"><div class="capline">${alabel(a)}<span>AGENT / 0${i+1}</span></div><h2>${a.name}</h2><p>${a.desc}</p><div class="defrow"><span class="indicator">${v.working?'Working':S.session.mode==='ended'?'Complete':'Ready'}</span><button class="linkbtn" data-agent="${a.name}">Inspect agent ${ico('arrow')}</button></div></article>`}).join('')}</div><div class="two-col block-gap">${sources()}<section class="panel"><div class="panel-head"><h2>Handoff contract</h2></div><div class="config-body">${rule('route','No skipped gates','Scout → Filter → Analyst → Risk → Executor. Logger audits the entire path, including early exits.')}${rule('clock','Approvals expire','Screening evidence expires after 180 seconds. A Risk permit is single-use and expires after 8 seconds.')}${rule('shield','No substitutions','Missing launch history, ownership, LP or bundle data is an evidence kill. Unknown measurements are never zero.')}${rule('database','Durable audit','Every kill and handoff carries a cycle number, timestamp and available source evidence.')}</div></section></div>`}
function rule(icon,title,desc){return `<div class="policy-rule"><span class="rule-icon">${ico(icon)}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`}
const hardRules=[['Liquidity','≥ $40,000','DexScreener'],['1h volume','≥ $50,000','DexScreener'],['1h move','< +80%','DexScreener'],['Mint authority','Revoked','Solana RPC'],['Freeze authority','Revoked','Solana RPC'],['Pool LP','100% locked / burned','RugCheck'],['Top 10 wallets','≤ 25%','Solana RPC'],['Creator holding','≤ 3%','RPC + RugCheck'],['Creator history','No indexed past rugs','RugCheck'],['Initial bundles','≤ 10%','Launch-bundle index']];
function policyPage(){return head('SYSTEM / MANDATE','Risk policy','The active mandate is enforced by the worker, not just displayed here.',`<span class="paper-tag">${ico('lock')} READ-ONLY POLICY</span>`)+`<div class="mini-kpi-grid">${kpi('Max allocation','8%','All-in cost / marked equity')}${kpi('Protective stop','−6%','Armed before entry')}${kpi('Trail activation','+12%','6% below observed peak')}${kpi('Score threshold','70/100','All six factors required')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Hard filter gates</h2><p>Scout first: age 30m–72h, market cap $300K–$20M.</p></div></div><div class="table-wrap"><table><thead><tr><th>Check</th><th>Pass condition</th><th>Source</th></tr></thead><tbody>${hardRules.map(r=>`<tr><td style="font-family:var(--sans)">${r[0]}</td><td>${esc(r[1])}</td><td class="dim" style="font-size:9px">${r[2]}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Scoring model</h2><p>Deterministic, capped factors. No proxy for missing data.</p></div></div><div class="config-body">${[['Momentum',20,'1h move: 0% to +40%'],['Unique buyers',20,'0–300 distinct indexed buyers / 1h'],['Buy / sell ratio',15,'0.75× to 2×; positive buys with no sells earn full credit'],['Holder growth',20,'0% to +10% over matched ~15m owner snapshots'],['Liquidity / cap',15,'0% to 20% depth against observed market cap'],['Smart wallets',10,'0–3 distinct matched buyers in the latest swap sample']].map(a=>`<div class="factor"><label>${a[0]}<b>${a[1]} pts</b></label><div class="factor-bar"><i style="width:${a[1]*4}%"></i></div><small>${a[2]}</small></div>`).join('')}</div></section></div><div class="two-col block-gap"><section class="panel"><div class="panel-head"><h2>Evidence boundaries</h2></div><div class="config-body">${rule('radar','Discovery is bounded','Latest DexScreener profiles and boosts, new/trending GeckoTerminal pools, and retained mints. This is not an exhaustive scan of every Solana pool. Market cap must be present; FDV is not a substitute.')}${rule('layers','Wallet concentration','The RPC census aggregates all accounts by owner and reconciles to supply. Vaults are included conservatively. The creator is the RugCheck-attributed deployer.')}${rule('log','Indexed creator history','Each reported prior mint must carry an explicit non-rug verdict. Missing lists, truncated histories, and unverified prior reports block entry. Off-index history cannot be ruled out.')}${rule('filter','Launch bundles','Only an initial bundled-supply percentage is accepted. Current bundler balances and same-slot trades are not substitutes.')}</div></section><section class="panel"><div class="panel-head"><h2>Paper execution</h2></div><div class="config-body">${rule('wallet','No key, no broadcast','Simulated USD only. One entry per mint per session, no leverage, no averaging down. Higher scores receive priority.')}${rule('shield','Stop and trail','The stop starts at 94% of the modeled entry. At +12%, a 6% high-water trail activates; it can tighten but never loosen.')}${rule('clock','Two-sided references','Risk needs an exact-pool buy and sell observed within 90s before entry. A modeled immediate exit must retain more than 94% of the all-in budget. A paper exit needs a recent sell. These are trade prints, not executable quotes.')}${rule('pulse','Monitor continuity','Risk polls every 20s. A monitor gap over 60s blocks entries; existing exposure is queued for exit at fresh market evidence. The eventual loss may exceed 6%.')}${rule('moon','At the cutoff','New entries stop at 07:00 EAT. Open positions flatten at the next valid quote. A missing quote leaves the exit pending; it never creates a fictional fill.')}${rule('target','Smart-wallet cohort','Optional allowlist plus observed traders with ≥3 completed round trips across ≥2 other mints, positive net P&L and ≥2/3 wins before the buy. Latest ≤300 indexed swaps; not full-wallet attribution.')}</div></section></div>`}
function logPage(){return head('APPEND-ONLY LEDGER','Audit log','Every kill, admission, handoff and paper fill, in timestamp order.',`<a class="btn" href="/api/ledger.csv" download>${ico('export')}Export full CSV</a>`)+`<section class="panel"><div class="panel-head"><div class="heading-line"><h2>Decision stream</h2><span class="tiny-pip">${fmt(S.stats.events)} events</span></div>${liveFlag()}</div><div class="controls"><div class="audit-controls"><select class="filter-select" id="log-kind" aria-label="Filter by event type"><option value="">All events</option>${['KILL','HANDOFF','ENTRY','EXIT','TRAIL','CYCLE','SCAN','SOURCE','SESSION','CONTROL','ERROR','BOOKED','EXIT_ORDER','TAPE_CHECK','MONITOR_GAP','WORKER'].map(k=>`<option ${logState.kind===k?'selected':''}>${k}</option>`).join('')}</select><select class="filter-select" id="log-agent" aria-label="Filter by agent"><option value="">All agents</option>${agents.map(a=>`<option ${logState.agent===a.name?'selected':''}>${a.name}</option>`).join('')}</select></div><label class="searchbox">${ico('search')}<input id="log-search" type="search" placeholder="Search decisions…" value="${esc(logState.q)}" aria-label="Search audit log" autocomplete="off"></label></div><div id="log-content">${logData?logRows(logData):empty('clock','Reading the ledger','Loading persisted decision records…')}</div></section>`}
function logRows(d){return `${d.rows.length?`<div class="table-wrap"><table class="log-table"><thead><tr><th>Time · EAT</th><th>Cycle</th><th>Agent</th><th>Event</th><th>Decision / evidence</th><th></th></tr></thead><tbody>${d.rows.map(e=>`<tr class="clickrow" data-event="${e.id}" tabindex="0"><td class="stamp">${hh(e.ts,true)}</td><td class="dim">${String(e.scan).padStart(3,'0')}</td><td>${esc(e.agent)}</td><td>${kindBadge(e.kind)}</td><td class="log-reason">${e.symbol?`<span class="log-sym">${esc(e.symbol)}</span>`:''}${esc(e.reason)}</td><td>${ico('chev','row-arrow')}</td></tr>`).join('')}</tbody></table></div>`:empty('search','No matching decisions','Try a different agent, event type or search term.')}<div class="table-foot"><span>${d.total?d.offset+1:0}–${Math.min(d.offset+d.rows.length,d.total)} of ${fmt(d.total)} events</span><div class="pager"><button class="icon-button" data-page="-1" aria-label="Previous page" ${d.offset===0?'disabled':''}>${ico('left')}</button><button class="icon-button" data-page="1" aria-label="Next page" ${d.offset+d.limit>=d.total?'disabled':''}>${ico('chev')}</button></div></div>`}
async function loadLog(){if(page!=='log')return;const seq=++logSeq;try{const q=new URLSearchParams({...logState,limit:30});const d=await api('/api/events?'+q);if(seq!==logSeq||page!=='log')return;logData=d;if($('#log-content'))$('#log-content').innerHTML=logRows(d)}catch(e){if(seq===logSeq)toast('Audit log: '+e.message)}}
function render(){if(!S)return;const input=document.activeElement;if(input?.matches('input,select')&&$main.contains(input)&&polling)return;nav();let out=offline?`<div class="notice">Connection lost. Showing the last received state; live status is not verified.</div>`:sourceStale()?`<div class="notice">Worker heartbeat is stale. Last received ${hh(S.session.heartbeat)} EAT.</div>`:'';if(S.session.mode==='paused')out+=`<div class="notice">Session paused. New entries are disabled; open-position risk monitoring continues.</div>`;if(page==='overview'){out+=head('WORKSPACE / COMMAND CENTER','Desk overview','Live Solana discovery, hard filters and paper execution.',buttons())+overviewHero()+pipeline()+feedTable()+`<div class="low-grid block-gap">${miniAudit()}${guardSummary()}</div>`}else if(page==='feed'){out+=head('SCOUT / INTELLIGENCE','Candidate feed','Inspect the evidence behind each in-range pair. Unscored pairs are not trade signals.',buttons())+`<div class="mini-kpi-grid">${kpi('Screened',fmt(S.stats.screened),'Pairs in the latest scan')}${kpi('In range',pad(S.stats.in_range),'Inside age and cap bounds','positive')}${kpi('Rejected',pad(S.stats.kills),'Failed or unverifiable evidence')}${kpi('Scored 70+',pad(S.stats.qualified),'Complete Analyst handoffs')}</div>`+feedTable(true)}else if(page==='book')out+=bookPage();else if(page==='agents')out+=agentPage();else if(page==='policy')out+=policyPage();else if(page==='log')out+=logPage();$main.innerHTML=out;if(page==='log')loadLog()}
async function refresh(quiet=false){if(polling)return;polling=true;try{S=await api('/api/state');delta=S.now-Date.now()/1000;offline=false;render()}catch(e){offline=true;if(!S)$main.innerHTML=`<div class="initial"><div class="eyebrow">CONNECTION STATUS</div><h1>Desk unavailable</h1><p>The worker has not returned a state. Reconnecting automatically.</p><button class="btn" style="margin-top:15px" data-retry>Retry connection</button></div>`;else render()}finally{polling=false}}
function flipPage(){page=selTab();document.body.classList.remove('nav-open');closeDrawer(false);nav();render();window.scrollTo(0,0);document.title=(tabs.find(t=>t[0]===page)||tabs[0])[1]+' · Nightshift'}
let restoreFocus=null;function closeDrawer(restore=true){modalSeq++;drawerKind='';chartPair='';$('#drawer-root').innerHTML='';document.body.style.overflow='';if(restore&&restoreFocus?.isConnected)restoreFocus.focus({preventScroll:true});restoreFocus=null}
function drawer(title,html,kind='info'){if(!drawerKind)restoreFocus=document.activeElement;drawerKind=kind;const id=++modalSeq;$('#drawer-root').innerHTML=`<div class="overlay" data-close></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-top"><span>${esc(title)}</span><button class="icon-button" data-close aria-label="Close details">${ico('x')}</button></div><div class="drawer-content">${html}</div></aside>`;document.body.style.overflow='hidden';$('.drawer-top button').focus({preventScroll:true});return id}
const dgrid=arr=>`<div class="details-grid">${arr.map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>`;
function checkList(ch){return ch.map(c=>`<div class="check-row"><span class="check-result ${c.result}">${ico(c.result==='pass'?'check':c.result==='fail'?'x':'info')}</span><span class="check-details"><b>${esc(c.key)}</b><small>${esc(c.source)}</small></span><span class="check-value">${esc(c.value)}</span></div>`).join('')}
function eventList(evs){return evs.map(e=>`<div class="detail-ev"><time>${hh(e.ts,true)}</time><div><b>${esc(e.agent)} · ${esc(e.kind)}</b><p>${esc(e.reason)}</p></div></div>`).join('')}
async function openPair(id){const token=drawer('Candidate evidence',empty('radar','Reading evidence','Retrieving this pair’s most recent evaluation.'),'pair');let p;try{p=await api('/api/pair/'+encodeURIComponent(id))}catch(e){if(token===modalSeq)$('.drawer-content').innerHTML=empty('alert','Evidence unavailable',esc(e.message));return}if(token!==modalSeq)return;chartPair=id;chartRange='1H';const tested=p.checks.filter(x=>!['Market cap','Pair age'].includes(x.key)).length;$('.drawer-content').innerHTML=`<div class="detail-token">${avatar(p)}<div><h2>${esc(p.symbol)}</h2><p>${esc(p.name)} · ${esc(p.dex)}</p></div>${badge(p.status)}</div><div class="mintrow"><span>Mint</span><button data-copy="${esc(p.mint)}" title="Copy full mint address">${short(p.mint)} ${ico('copy')}</button><a href="https://dexscreener.com/solana/${esc(p.pair)}" target="_blank" rel="noopener noreferrer">DexScreener ${ico('ne')}</a></div><div class="detail-card"><div class="capline"><h3>Pair snapshot</h3><span>${hh(p.seen,true)} EAT</span></div>${dgrid([['Market cap',usd(p.mcap)],['Liquidity',usd(p.liq)],['1h volume',usd(p.vol)],['Pair age',age(p.created)],['1h move',`<span class="${p.change>=0?'positive':'negative'}">${pc(p.change)}</span>`],['Analyst score',p.score==null?'Not scored':fmt(p.score,2)+'/100']])}</div><div class="detail-card"><div class="capline"><h3>Observed price</h3><div class="segmented">${['1H','6H','24H'].map(x=>`<button class="${x==='1H'?'sel':''}" data-range="${x}">${x}</button>`).join('')}</div></div><div id="chart-host" class="chart-host"><p>Loading indexed candles…</p></div><div class="chart-foot" id="chart-foot"><span>GeckoTerminal · USD close</span></div></div><div class="detail-card"><div class="capline"><h3>Gate evidence</h3><span>${esc(p.agent)} / cycle ${p.scan}</span></div>${checkList(p.checks)}${tested<10?`<p class="sub" style="margin-top:10px">${10-tested} hard checks not evaluated. Upstream rejection stops the handoff.</p>`:''}</div>${p.factors.length?`<div class="detail-card"><h3>Score breakdown · ${p.score}/100</h3>${p.factors.map(f=>`<div class="factor"><label>${esc(f.key)}<b>${f.points} / ${f.max}</b></label><div class="factor-bar"><i style="width:${f.points/f.max*100}%"></i></div><small>${esc(f.value)} · ${esc(f.source)}</small></div>`).join('')}</div>`:''}<div class="detail-card"><h3>Pair audit trail</h3>${eventList(p.events)}</div><div class="data-strip">${ico('info')}Discovery is not an endorsement. Missing evidence blocks entry.</div>`;loadChart(id,'1H',token)}
async function loadChart(pair,range,seq){const host=$('#chart-host');if(!host)return;host.innerHTML='<p>Loading indexed candles…</p>';try{const d=await api('/api/chart?'+new URLSearchParams({pair,range}));if(modalSeq!==seq||chartRange!==range)return;const rows=d.rows.filter(r=>finite(r[4])&&r[4]>0);if(rows.length<2){host.innerHTML='<p>Not enough observed candles in this window.</p>';return}const lo=Math.min(...rows.map(r=>r[4])),hi=Math.max(...rows.map(r=>r[4])),t0=rows[0][0],t1=rows.at(-1)[0],span=Math.max(hi-lo,hi*.0001),pts=rows.map(r=>[(r[0]-t0)/Math.max(t1-t0,1)*390+2,80-((r[4]-lo)/span)*65]);const path=pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');host.innerHTML=`<svg viewBox="0 0 395 95" preserveAspectRatio="none" aria-label="Real indexed close prices"><defs><linearGradient id="chartfill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#afdd7f" stop-opacity=".25"/><stop offset="1" stop-color="#afdd7f" stop-opacity=".01"/></linearGradient></defs>${[18,47,79].map(y=>`<path d="M0 ${y}H395" stroke="#39432f" stroke-dasharray="3 4" stroke-width=".6"/>`).join('')}<path d="${path}L392 94H2Z" fill="url(#chartfill)"/><path d="${path}" stroke="#b7de91" fill="none" stroke-width="1.7" vector-effect="non-scaling-stroke"/></svg>`;$('#chart-foot').innerHTML=`<span>${hh(t0)}–${hh(t1)} EAT · ${d.interval}m bars</span><span>${price(rows.at(-1)[4])}</span>`}catch(e){if(modalSeq===seq&&range===chartRange)host.innerHTML='<p>Price history unavailable. No synthetic candles.</p>'}}
async function openEvent(id){const seq=drawer('Journal / decision record',empty('log','Reading event','Loading immutable audit evidence.'),'event');try{const e=await api('/api/event?id='+id);if(seq!==modalSeq)return;$('.drawer-content').innerHTML=`<div class="capline">${kindBadge(e.kind)}<span class="micro dim">EVENT #${e.id}</span></div><h2 style="font-size:25px;letter-spacing:-1px;margin:17px 0 4px">${esc(e.agent)}${e.symbol?' · '+esc(e.symbol):''}</h2><p class="muted" style="font-size:12px">${day(e.ts)} · ${hh(e.ts,true)} EAT · Cycle ${e.scan}</p><div class="callout">${ico('file')}<span>${esc(e.reason)}</span></div>${e.detail.checks?`<div class="detail-card"><h3>Evidence at decision time</h3>${checkList(e.detail.checks)}</div>`:''}<div class="detail-card"><h3>Persisted payload</h3><pre class="raw">${esc(JSON.stringify(e.detail,null,2))}</pre></div>${e.pair?`<button class="btn sm" style="margin-top:14px" data-pair="${esc(e.pair)}">Latest pair snapshot ${ico('arrow')}</button>`:''}` }catch(e){if(seq===modalSeq)$('.drawer-content').innerHTML=empty('alert','Event unavailable',esc(e.message))}}
async function openAgent(name){const a=agents.find(x=>x.name===name);if(!a)return;const v=S.agents.find(x=>x.name===name);const seq=drawer('Pipeline / agent '+pad(agents.indexOf(a)+1),`${alabel(a)}<h2 style="font-size:28px;letter-spacing:-1px;margin:12px 0 6px">${name}</h2><p class="muted" style="font-size:13px">${a.desc}</p><div class="detail-card"><h3>Handoff contract</h3><p class="sub" style="margin-top:8px;font-size:12px">${a.out}</p>${dgrid([['State',v.working?'Working':'Ready'],['Events',fmt(v.count)],['Last activity',v.last?hh(v.last.ts):'None yet']])}</div><div class="detail-card"><h3>Agent activity</h3><div id="agent-activity"><p class="sub">Reading journal…</p></div></div>`,'agent');try{const d=await api('/api/events?agent='+name+'&limit=10');if(seq===modalSeq)$('#agent-activity').innerHTML=d.rows.length?eventList(d.rows):`<p class="sub" style="margin-top:10px">No handoffs received this session. Upstream gates remain enforced.</p>`}catch(e){if(seq===modalSeq)$('#agent-activity').textContent='Journal unavailable.'}}
function openSession(){const s=S.session;drawer('Session / overnight schedule',`${liveFlag()}<h2 style="font-size:25px;margin:13px 0">Overnight session</h2><p class="muted">${day(s.start)} · Africa/Kampala</p><div class="detail-card"><h3>Session window</h3>${dgrid([['Started',hh(s.start)+' EAT'],['Cutoff',hh(s.end)+' EAT'],['Cycles',fmt(s.scans)],['Scan cadence','3 min'],['Risk polling','20 sec'],['Mode','Paper only']])}</div><div class="detail-card"><h3>Worker heartbeat</h3><p class="sub">Last seen ${hh(s.heartbeat,true)} EAT. The desk runs without an open browser while the hosting process stays alive. An always-on host is required for guaranteed overnight uptime.</p></div><div class="detail-card"><h3>Session identifier</h3><p class="raw">${esc(s.id)}</p><p class="sub">At cutoff: stop entries, flatten at valid market quotes and write the morning report. Start a new session explicitly.</p></div>`)}
function openPosition(id){const p=S.book.positions.find(p=>p.id===id);if(!p)return;drawer('Paper book / position',`<div class="detail-token">${avatar(p)}<div><h2>${esc(p.symbol)}</h2><p>${p.closed?'Closed':'Open'} paper position · ${hh(p.entered)} EAT</p></div></div><div class="detail-card"><h3>Execution record</h3>${dgrid([['All-in cost',cash(p.cost)],['Entry fill',price(p.entry)],['Token quantity',fmt(p.qty,3)],['Last mark',price(p.mark)],['High-water mark',price(p.peak)],['Current stop',price(p.stop)],['Trail',p.armed?'Active':'Not armed'],['Last quote',hh(p.marked,true)],['Exit',p.closed?price(p.exit):p.pending_exit?'Pending':'—']])}</div><div class="detail-card"><h3>Reference swaps</h3><p class="sub">Observed market transactions, not transactions made by this desk.</p><p class="raw">Entry: ${esc(p.entry_tx)}</p>${p.exit_tx?`<p class="raw">Exit: ${esc(p.exit_tx)} · ${esc(p.reason)}</p>`:''}</div><button class="btn" style="margin-top:15px" data-pair="${esc(p.pair)}">Inspect pair ${ico('arrow')}</button>`)}
async function action(a){if(busy)return;busy=true;render();try{const r=await api('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-Desk-Action':'paper-control'},body:JSON.stringify({action:a})});toast(r.message);if(a==='scan'||a==='resume')await new Promise(res=>setTimeout(res,300));await refresh()}catch(e){toast(e.message)}finally{busy=false;render()}}
function updateFeedInput(){const rows=filtPairs();if($('#feed-body'))$('#feed-body').innerHTML=feedRows(rows,true);if($('#feed-empty'))$('#feed-empty').innerHTML=rows.length?'':empty('search','No matching pairs','Try another symbol or mint address.')}
let debounce;document.addEventListener('input',ev=>{if(ev.target.id==='feed-search'){feedState.q=ev.target.value;updateFeedInput()}if(ev.target.id==='log-search'){logState.q=ev.target.value;logState.offset=0;clearTimeout(debounce);debounce=setTimeout(loadLog,200)}});document.addEventListener('change',ev=>{if(ev.target.id==='log-kind'||ev.target.id==='log-agent'){logState[ev.target.id==='log-kind'?'kind':'agent']=ev.target.value;logState.offset=0;loadLog()}});
document.addEventListener('click',ev=>{const t=ev.target.closest('[data-close],[data-pair],[data-agent],[data-event],[data-action],[data-filter],[data-sort],[data-book],[data-page],[data-position],[data-range],[data-copy],[data-sources],[data-session],[data-retry],#mobile-menu,#nav-scrim');if(!t)return;const d=t.dataset;if(t.id==='mobile-menu'){document.body.classList.toggle('nav-open');return}if(t.id==='nav-scrim'){document.body.classList.remove('nav-open');return}if('close'in d){closeDrawer();return}if('retry'in d){refresh();return}if(d.pair){openPair(d.pair);return}if(d.event){openEvent(Number(d.event));return}if(d.agent){openAgent(d.agent);return}if('sources'in d){drawer('System / feed health',sources()+`<div class="callout amber">${ico('shield')}Unavailable or incomplete evidence cannot pass a hard gate. A connected source does not guarantee coverage for every mint.</div><p class="sub">A server-side SolanaTracker read-only API key can enable the optional initial-bundle and complete creator-history adapters. Never enter a wallet private key.</p>`);return}if('session'in d){openSession();return}if(d.action){action(d.action);return}if(d.filter){feedState.filter=d.filter;render();return}if(d.sort){feedState.dir=feedState.sort===d.sort?-feedState.dir:-1;feedState.sort=d.sort;render();return}if(d.book){bookTab=d.book;render();return}if(d.position){openPosition(Number(d.position));return}if(d.page){logState.offset=Math.max(0,logState.offset+Number(d.page)*30);loadLog();return}if(d.range&&chartPair){chartRange=d.range;document.querySelectorAll('[data-range]').forEach(b=>b.classList.toggle('sel',b.dataset.range===d.range));loadChart(chartPair,d.range,modalSeq);return}if(d.copy){(async()=>{try{await navigator.clipboard.writeText(d.copy);toast('Mint address copied')}catch(e){const box=document.createElement('textarea');box.value=d.copy;box.setAttribute('readonly','');t.parentNode.after(box);box.select();try{if(document.execCommand('copy')){box.remove();toast('Mint address copied')}else toast('Select and copy the full address shown')}catch(e){toast('Select and copy the address shown')}}})();}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeDrawer();document.body.classList.remove('nav-open')}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('tr[tabindex],g[tabindex]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(ev.key==='Tab'&&drawerKind){const els=Array.from(document.querySelectorAll('.drawer a[href],.drawer button:not([disabled]),.drawer input,.drawer textarea')).filter(el=>el.getClientRects().length);if(els.length&&((ev.shiftKey&&document.activeElement===els[0])||(!ev.shiftKey&&document.activeElement===els.at(-1)))){ev.preventDefault();els[ev.shiftKey?els.length-1:0].focus()}}});
window.addEventListener('hashchange',flipPage);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh(true)});flipPage();refresh();setInterval(()=>{if(!document.hidden)refresh(true)},10000);function tick(){$('#clock').innerHTML=hh(now(),true)+' <em>EAT</em>'}tick();setInterval(tick,1000);
